typedef Triangulation::Face_handle Face_handle;
typedef Triangulation::Vertex_handle Vertex_handle;
typedef Triangulation::Face Face;
typedef Triangulation::Point Point;

// Create a property map for face labels (0 = unvisited, 1 = interior, 2 = exterior)
std::map<Face_handle, int> face_labels;

// Initialize queue for BFS
std::queue<Face_handle> queue;

// Get all faces and mark constraint faces
std::list<Face_handle> faces_to_process;
for (Face_handle f : triangulation.all_faces()) {
    faces_to_process.push_back(f);
}

// Find a face that is definitely outside (use infinite face)
Face_handle infinite_face = triangulation.infinite_face();
queue.push(infinite_face);
face_labels[infinite_face] = 2; // Mark as exterior

// BFS traversal for face labeling
while (!queue.empty()) {
    Face_handle current = queue.front();
    queue.pop();

    // Process neighbors
    for (int i = 0; i < 3; i++) {
        Face_handle neighbor = current->neighbor(i);
        if (neighbor->has_vertex(triangulation.infinite_vertex())) {
            face_labels[neighbor] = 2; // Mark as exterior
        }

        if (face_labels.find(neighbor) == face_labels.end()) {
            // Not yet visited
            bool is_constrained = false;
            int incident_constraints = 0;

            // Count how many constrained edges are incident to this face
            for (int j = 0; j < 3; j++) {
                if (triangulation.is_constrained(std::make_pair(neighbor, j))) {
                    incident_constraints++;
                }
            }

            // If crossing a constrained edge, flip the label
            if (incident_constraints > 0) {
                // Crossing constraint - flip label
                if (face_labels[current] == 1) {
                    face_labels[neighbor] = 2;
                } else {
                    face_labels[neighbor] = 1;
                }
            } else {
                // No constraint crossing - keep same label
                face_labels[neighbor] = face_labels[current];
            }
            queue.push(neighbor);
        }
    }
}

// Second pass: assign final labels to all faces
for (Face_handle f : triangulation.all_faces()) {
    if (f != nullptr && face_labels.find(f) == face_labels.end()) {
        // If not labeled yet, use default exterior
        face_labels[f] = 2;
    }
}

// Apply labels to triangulation faces
for (auto it = face_labels.begin(); it != face_labels.end(); ++it) {
    it->first->info().set_label(it->second);
}
// END_CODE

